// ========== src/pages/inventory/Vendors.jsx ==========
import React, { useState } from 'react';
import {
  Card, Table, Button, Modal, Form, Input, InputNumber, Switch, message, Space, Tag
} from 'antd';
import {
  PlusOutlined, EditOutlined, DeleteOutlined, PhoneOutlined, MailOutlined,
  EyeOutlined
} from '@ant-design/icons';
import { useQuery, useMutation, useQueryClient } from 'react-query';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import { formatPKR, VALIDATION } from '../../config/constants';
import { parseAmount } from '../../utils/decimalUtils';
import { nameRules, codeRules, optionalPhoneRules, optionalEmailRules, addressRules, notesRules, optionalAmountRules } from '../../utils/validationRules';
import { getErrorMessage } from '../../utils/errorMessages';

const Vendors = () => {
  const queryClient = useQueryClient();
  const navigate = useNavigate();
  const [modalVisible, setModalVisible] = useState(false);
  const [editingVendor, setEditingVendor] = useState(null);
  const [form] = Form.useForm();

  const { data: vendors, isLoading } = useQuery('vendors', async () => {
    const response = await axios.get('/inventory/vendors');
    return response.data.data;
  });

  const vendorMutation = useMutation(
    (data) => {
      if (editingVendor) {
        return axios.put(`/inventory/vendors/${editingVendor.id}`, data);
      }
      return axios.post('/inventory/vendors', data);
    },
    {
      onSuccess: () => {
        message.success(`Vendor ${editingVendor ? 'updated' : 'created'} successfully`);
        queryClient.invalidateQueries('vendors');
        handleCloseModal();
      },
      onError: (error) => {
        const operation = editingVendor ? 'update' : 'create';
        const errorMessage = getErrorMessage(error, 'vendor', operation);
        message.error(errorMessage);
      }
    }
  );

  const deleteMutation = useMutation(
    (id) => axios.delete(`/inventory/vendors/${id}`),
    {
      onSuccess: () => {
        message.success('Vendor deleted successfully');
        queryClient.invalidateQueries('vendors');
      },
      onError: (error) => {
        const errorMessage = getErrorMessage(error, 'vendor', 'delete');
        message.error(errorMessage);
      }
    }
  );

  const handleCloseModal = () => {
    setModalVisible(false);
    setEditingVendor(null);
    form.resetFields();
  };

  const handleView = (record) => {
    navigate(`/app/inventory/vendors/${record.id}`);
  };

  const columns = [
    {
      title: 'Name',
      dataIndex: 'name',
      key: 'name'
    },
    {
      title: 'Code',
      dataIndex: 'code',
      key: 'code',
      render: (code) => <Tag>{code}</Tag>
    },
    {
      title: 'Contact Person',
      dataIndex: 'contactPerson',
      key: 'contactPerson'
    },
    {
      title: 'Phone',
      dataIndex: 'phone',
      key: 'phone',
      render: (phone) => phone && (
        <Space>
          <PhoneOutlined />
          {phone}
        </Space>
      )
    },
    {
      title: 'Email',
      dataIndex: 'email',
      key: 'email',
      render: (email) => email && (
        <Space>
          <MailOutlined />
          {email}
        </Space>
      )
    },
    {
      title: 'Tax Number',
      dataIndex: 'taxNumber',
      key: 'taxNumber',
      render: (taxNumber) => taxNumber || '-'
    },
    {
      title: 'Payment Terms',
      dataIndex: 'paymentTerms',
      key: 'paymentTerms',
      render: (terms) => terms || '-'
    },
    {
      title: 'Current Balance',
      dataIndex: 'currentBalance',
      key: 'currentBalance',
      render: (balance) => balance ? formatPKR(Number(balance)) : formatPKR(0)
    },
    {
      title: 'Actions',
      key: 'actions',
      render: (_, record) => (
        <Space>
          <Button
            icon={<EyeOutlined />}
            onClick={() => handleView(record)}
          />
          <Button
            icon={<EditOutlined />}
            onClick={() => {
              setEditingVendor(record);
              form.setFieldsValue(record);
              setModalVisible(true);
            }}
          />
          <Button
            icon={<DeleteOutlined />}
            danger
            onClick={() => {
              Modal.confirm({
                title: 'Delete Vendor',
                content: 'Are you sure? This will affect all related purchase orders.',
                onOk: () => deleteMutation.mutate(record.id)
              });
            }}
          />
        </Space>
      )
    }
  ];

  return (
    <Card
      title="Vendors"
      extra={
        <Button
          type="primary"
          icon={<PlusOutlined />}
          onClick={() => setModalVisible(true)}
        >
          Add Vendor
        </Button>
      }
    >
      <Table
        rowKey="id"
        columns={columns}
        dataSource={vendors}
        loading={isLoading}
        scroll={{ x: 800 }}
      />

      <Modal
        title={editingVendor ? 'Edit Vendor' : 'Add Vendor'}
        open={modalVisible}
        onCancel={handleCloseModal}
        footer={null}
        width={700}
      >
        <Form
          form={form}
          layout="vertical"
          onFinish={(values) => {
            // Convert opening balance to number for backend
            const processedValues = {
              ...values,
              openingBalance: values.openingBalance ? parseAmount(values.openingBalance) : 0
              // NOTE: currentBalance removed - VendorLedger is the single source of truth
            };
            vendorMutation.mutate(processedValues);
          }}
        >
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 16 }}>
            <Form.Item
              label="Name"
              name="name"
              rules={nameRules}
            >
              <Input placeholder="e.g., ABC Electronics" maxLength={100} showCount />
            </Form.Item>

            <Form.Item
              label="Code"
              name="code"
              rules={codeRules}
            >
              <Input placeholder="e.g., ABC-001" maxLength={20} />
            </Form.Item>

            <Form.Item label="Contact Person" name="contactPerson">
              <Input placeholder="Contact person name" maxLength={100} />
            </Form.Item>

            <Form.Item
              label="Phone"
              name="phone"
              rules={optionalPhoneRules}
            >
              <Input placeholder="03001234567 (11 digits)" maxLength={11} />
            </Form.Item>

            <Form.Item
              label="Email"
              name="email"
              rules={optionalEmailRules}
            >
              <Input placeholder="vendor@example.com" maxLength={100} />
            </Form.Item>

          </div>

          <Form.Item label="Address" name="address" rules={addressRules}>
            <Input.TextArea rows={2} placeholder="Complete address" maxLength={500} showCount />
          </Form.Item>

          <div style={{ display: 'grid', gridTemplateColumns: editingVendor ? '1fr 1fr' : '1fr 1fr 1fr', gap: 16 }}>
            <Form.Item label="Tax Number" name="taxNumber">
              <Input placeholder="e.g., 12345-6789012-3" maxLength={50} />
            </Form.Item>

            <Form.Item label="Payment Terms" name="paymentTerms">
              <Input placeholder="e.g., Net 30, Due on Receipt" maxLength={100} />
            </Form.Item>

            {!editingVendor && (
              <Form.Item
                label="Opening Balance (PKR)"
                name="openingBalance"
                rules={optionalAmountRules}
              >
                <InputNumber style={{ width: '100%' }} precision={2} min={0} max={VALIDATION.MAX_AMOUNT} step={0.01} placeholder="0.00" />
              </Form.Item>
            )}
          </div>

          <div style={{ textAlign: 'right' }}>
            <Space>
              <Button onClick={handleCloseModal}>Cancel</Button>
              <Button type="primary" htmlType="submit" loading={vendorMutation.isLoading}>
                {editingVendor ? 'Update' : 'Create'}
              </Button>
            </Space>
          </div>
        </Form>
      </Modal>
    </Card>
  );
};

export default Vendors;